:root {
  color-scheme: dark;
}

html,body {
  margin: 0;
  height: 100%;
  background: #0a0a0a;
}

body {
  font-family: system-ui,-apple-system,Segoe UI,Roboto,Helvetica,Arial,sans-serif;
}

.page {
  min-height: 100vh;
  display: grid;
  place-items: center;
  padding: 24px;
  background: #0a0a0a;
  color: #e5e7eb;
}

.card {
  width: min(700px,100%);
  background: #0b1020;
  border: 1px solid #1f2937;
  border-radius: 14px;
  padding: 18px;
  display: grid;
  gap: 14px;
}

h1 {
  margin: 0;
  font-size: 22px;
  font-weight: 800;
}

.subtitle {
  margin: 0;
  color: #9ca3af;
  font-size: 13px;
}

.status-row {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

.pill {
  border: 1px solid #334155;
  border-radius: 999px;
  padding: 6px 10px;
  font-size: 12px;
  color: #d1d5db;
  background: #0a0f1e;
}

.pill--danger {
  border-color: #7f1d1d;
  color: #fecaca;
  background: rgba(127,29,29,.25);
}

.actions {
  display: flex;
  gap: 10px;
}

.ghost {
  background: transparent;
  color: #e5e7eb;
  border: 1px solid #374151;
  border-radius: 12px;
  padding: 10px 14px;
  font-weight: 700;
  cursor: pointer;
}

.ghost:hover {
  border-color: #60a5fa;
}

.board {
  width: min(560px,100%);
  display: grid;
  gap: 4px;
  border-radius: 12px;
  background: #0a0f1e;
  border: 1px solid #334155;
  padding: 8px;
}

.cell {
  aspect-ratio: 1/1;
  border-radius: 4px;
  background: #111827;
}

.cell--snake {
  background: #2563eb;
}

.cell--head {
  background: #93c5fd;
}

.cell--food {
  background: #f43f5e;
}

.hint {
  margin: 0;
  color: #94a3b8;
  font-size: 12px;
}

